def transform(grid):
    g = np.array(grid)
    rows_uniform = all(len(set(r.tolist())) == 1 for r in g)
    if rows_uniform:
        seq = g[:, 0].tolist()
    else:
        seq = g[0, :].tolist()

    def shape(s):
        return [[c] for c in s] if rows_uniform else [list(s)]

    emit(shape(seq), "Collapse the stripes: one cell per input " +
         ("row (rows are uniform), giving a column." if rows_uniform
          else "column (columns are uniform), giving a row."))

    out = []
    for c in seq:
        if not out or out[-1] != c:
            out.append(c)
    res = shape(out)
    emit(res, "Merge runs of the same colour so each stripe appears exactly once.")
    return res
